<?php declare(strict_types=1);use yii\helpers\Html;
$rub=static fn(int$c):string=>($c<0?'−':'').number_format(abs($c)/100,2,',',' ').' ₽';$date=static fn(?string$v):string=>$v&&preg_match('/^(\d{4})-(\d{2})-(\d{2})/D',$v,$m)?$m[3].'.'.$m[2].'.'.$m[1]:'Не указан';$states=['missing_norm'=>'Норма не определена','planned'=>'Запланирован','blocked'=>'Заблокирован','ready'=>'Готов к расчёту','no_new_amount'=>'К выплате 0 ₽','completed'=>'Завершён'];
if($rows===[]):?><section class="fm2-otiz-empty" data-empty="<?=Html::encode($context)?>"><h2><?=Html::encode($listTitle)?></h2><p>Расчётных периодов пока нет. Подготовьте первый расчёт.</p></section>
<?php elseif($context==='history'):?><section class="fm2-otiz-snapshots fm2-otiz-archive fm2-otiz-surface"><h2><?=Html::encode($listTitle)?></h2><div class="shlz-table-wrap fm2-otiz-archive-wrap" data-mobile-strategy="contained-scroll" tabindex="0" aria-label="Архив расчётов"><table class="shlz-table" data-otiz-archive-table><thead class="shlz-table__head"><tr class="shlz-table__row"><?php foreach(['Расчётная дата','ID расчёта','Состояние расчёта','Автор и создание','Подтверждение','Объекты','Итог']as$h):?><th class="shlz-table__cell" scope="col"><?=$h?></th><?php endforeach?><th class="shlz-table__cell" scope="col"><span class="shlz-visually-hidden">Действия</span></th></tr></thead><tbody><?php foreach($rows as$r):$rid=(int)$r['id'];?><tr class="shlz-table__row"><td class="shlz-table__cell"><?=$date((string)$r['report_date'])?></td><td class="shlz-table__cell" data-snapshot-id="#<?=$rid?>">#<?=$rid?></td><td class="shlz-table__cell"><span class="shlz-status"><?=$r['status']==='accepted'?'Подтверждён':'На проверке'?></span></td><td class="shlz-table__cell"><?=Html::encode((string)($r['calculated_by_name']?:'Пользователь #'.(int)$r['calculated_by_user_id']))?><small><?=$date((string)$r['calculated_at'])?></small></td><td class="shlz-table__cell"><?=$r['accepted_at']?$date((string)$r['accepted_at']):'—'?></td><td class="shlz-table__cell"><?=(int)$r['object_count']?></td><td class="shlz-table__cell shlz-table__cell--numeric"><?=$rub((int)$r['total_pool_cents'])?></td><td class="shlz-table__cell fm2-otiz-archive-actions"><a class="shlz-table__affordance" href="/pilot/otiz/snapshots/<?=$rid?>" aria-label="Открыть расчёт #<?=$rid?>"><img src="/pilot/assets/shlz-icons/chevron-right-duo.svg" alt=""></a></td></tr><?php endforeach?></tbody></table></div></section>
<?php else:?><section class="fm2-otiz-snapshots"><h2><?=Html::encode($listTitle)?></h2><ul><?php foreach($rows as$r):?><li><a href="/pilot/otiz/snapshots/<?=(int)$r['id']?>"><span>Расчёт на <?=$date((string)$r['report_date'])?></span><strong><?=$rub((int)$r['total_pool_cents'])?></strong></a></li><?php endforeach?></ul></section><?php endif?>
